#!/usr/bin/env node
/**
 * Browser E2E for the PDF ingest flow.
 *
 * Usage:
 *   NODE_PATH=apps/web/node_modules node scripts/e2e_upload.js <pdf> [baseUrl]
 *
 * Flow: upload -> extract -> inspect preview -> publish -> open detail -> re-upload
 * (duplicate). Requires a running production server and the test session cookie
 * generated by scripts/make_session.js or the equivalent.
 */

const fs = require("fs");
const path = require("path");
const puppeteer = require("puppeteer-core");

const REPO = path.resolve(__dirname, "..");
const ENV_FILE = path.join(REPO, "apps/web/.env.local");

function readEnv() {
  if (!fs.existsSync(ENV_FILE)) return {};
  const env = {};
  for (const line of fs.readFileSync(ENV_FILE, "utf8").split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#") || !trimmed.includes("=")) continue;
    const i = trimmed.indexOf("=");
    let value = trimmed.slice(i + 1).trim();
    if (
      (value.startsWith('"') && value.endsWith('"')) ||
      (value.startsWith("'") && value.endsWith("'"))
    ) {
      value = value.slice(1, -1);
    }
    env[trimmed.slice(0, i).trim()] = value;
  }
  return env;
}

function slugify(value) {
  return value
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 60);
}

async function clickByText(page, selector, text, { exact = false } = {}) {
  const handles = await page.$$(selector);
  for (const handle of handles) {
    const label = (await handle.evaluate((el) => el.textContent || "")).trim();
    const matches = exact ? label === text : label.includes(text);
    if (matches) {
      await handle.evaluate((el) => el.scrollIntoView({ block: "center" }));
      await handle.click();
      return true;
    }
  }
  return false;
}

async function textOf(page) {
  return page.evaluate(() => document.body.innerText);
}

async function main() {
  const pdfArg = process.argv[2];
  if (!pdfArg) {
    console.error("Usage: node scripts/e2e_upload.js <pdf> [baseUrl]");
    process.exit(2);
  }

  const pdf = path.resolve(pdfArg);
  if (!fs.existsSync(pdf)) {
    console.error(`PDF not found: ${pdf}`);
    process.exit(2);
  }

  const baseUrl = (process.argv[3] || "http://localhost:3011").replace(/\/$/, "");
  const env = readEnv();
  const secret = process.env.NEXTAUTH_SECRET || env.NEXTAUTH_SECRET;
  if (!secret) {
    console.error("NEXTAUTH_SECRET is not set and not present in apps/web/.env.local");
    process.exit(2);
  }

  const { encode } = require("next-auth/jwt");
  const token = await encode({
    token: {
      name: "Pipeline Test",
      email: "pipeline.test@psgitech.ac.in",
      sub: "pipeline-test",
      picture: null,
      isAdmin: false,
    },
    secret,
    maxAge: 60 * 60,
  });

  const outDir = path.join(REPO, "scratch/screenshots", `e2e-${slugify(path.basename(pdf, ".pdf"))}`);
  fs.mkdirSync(outDir, { recursive: true });

  const checks = [];
  const consoleErrors = [];
  const pageErrors = [];
  const httpErrors = [];

  const check = (name, ok, detail) => {
    checks.push({ name, ok: Boolean(ok), detail });
    console.log(`  ${ok ? "PASS" : "FAIL"}  ${name}${detail ? ` (${detail})` : ""}`);
  };

  const browser = await puppeteer.launch({
    executablePath: process.env.CHROME_PATH || "/usr/bin/google-chrome",
    headless: true,
    args: ["--no-sandbox", "--disable-setuid-sandbox", "--disable-dev-shm-usage"],
    defaultViewport: { width: 1366, height: 868 },
  });

  const page = await browser.newPage();
  page.setDefaultTimeout(30_000);

  await page.setCookie({
    name: "next-auth.session-token",
    value: token,
    url: baseUrl,
    httpOnly: true,
    sameSite: "Lax",
  });

  page.on("console", (msg) => {
    if (msg.type() === "error") {
      const location = msg.location?.();
      consoleErrors.push(location?.url ? `${msg.text()} (${location.url})` : msg.text());
    }
  });
  page.on("pageerror", (err) => pageErrors.push(err.message));
  page.on("response", (res) => {
    if (res.status() >= 500) httpErrors.push(`${res.status()} ${res.url()}`);
  });

  let extraction = null;
  let published = null;

  async function uploadAndExtract(label) {
    await page.goto(`${baseUrl}/upload`, { waitUntil: "networkidle2" });
    if (page.url().includes("/login")) {
      throw new Error("Session cookie was rejected; /upload redirected to /login");
    }

    const input = await page.$("#pdf-upload");
    if (!input) throw new Error("Upload input #pdf-upload not found");
    await input.uploadFile(pdf);

    await page.waitForFunction(
      (name) => document.body.innerText.includes(name),
      { timeout: 15_000 },
      path.basename(pdf)
    );

    const clicked = await clickByText(page, 'button[type="submit"]', "Extract from PDF");
    if (!clicked) throw new Error("Extract button not found");

    await page.waitForFunction(
      () => {
        const text = document.body.innerText;
        return text.includes("Confirm & publish") || text.includes("Extraction error");
      },
      { timeout: 240_000, polling: 500 }
    );

    const body = await textOf(page);
    if (body.includes("Extraction error")) {
      const match = body.match(/Extraction error\s*\n?([\s\S]{0,400})/);
      throw new Error(`Extraction error: ${match ? match[1].trim() : "unknown"}`);
    }
    if (body.includes("Select a PDF file")) {
      throw new Error("Extraction never started; file selection was lost");
    }

    await page.screenshot({ path: path.join(outDir, `${label}-preview.png`), fullPage: true });

    const jsonClicked = await clickByText(page, "button", "Raw JSON", { exact: true });
    if (!jsonClicked) throw new Error("Raw JSON tab not found");
    await page.waitForSelector("pre");
    const raw = await page.$eval("pre", (el) => el.textContent || "");
    let parsed;
    try {
      parsed = JSON.parse(raw);
    } catch (error) {
      throw new Error(`Could not parse Raw JSON panel: ${error.message}`);
    }

    return parsed;
  }

  async function publish(label) {
    const buttons = await page.$$("button");
    let publishButton = null;
    for (const handle of buttons) {
      const labelText = (await handle.evaluate((el) => el.textContent || "")).trim();
      if (labelText.includes("Confirm & publish")) {
        publishButton = handle;
        break;
      }
    }
    if (!publishButton) throw new Error("Confirm & publish button not found");

    const disabled = await publishButton.evaluate((el) => el.disabled);
    if (disabled) {
      const title = await publishButton.evaluate((el) => el.getAttribute("title") || "");
      throw new Error(`Publish button is disabled: ${title}`);
    }

    await publishButton.evaluate((el) => el.scrollIntoView({ block: "center" }));
    await publishButton.click();

    await page.waitForFunction(
      () => {
        const text = document.body.innerText;
        return text.includes("Experience published") || text.includes("Already published");
      },
      { timeout: 60_000, polling: 250 }
    );

    const body = await textOf(page);
    const href = await page.evaluate(() => {
      const link = document.querySelector('a[href^="/experiences/"]');
      return link ? link.getAttribute("href") : null;
    });

    await page.screenshot({ path: path.join(outDir, `${label}-published.png`), fullPage: true });

    return {
      duplicate: body.includes("Already published"),
      assignedId: href ? href.split("/").filter(Boolean).pop() : null,
      href,
    };
  }

  try {
    console.log(`\nBrowser E2E: ${path.basename(pdf)}`);
    console.log(`Server: ${baseUrl}\n`);

    console.log("[1/6] Upload and extract");
    extraction = await uploadAndExtract("01");
    const exp = extraction.experiences?.[0] || {};
    const pipeline = extraction.pipeline || {};
    check("preview rendered", Array.isArray(extraction.experiences) && extraction.experiences.length > 0);
    check("company present", Boolean(exp.company?.name), exp.company?.name);
    check("candidate present", Boolean(exp.candidate?.name), exp.candidate?.name);
    check("rounds present", (exp.rounds?.length || 0) > 0, `${exp.rounds?.length || 0} rounds`);
    check("text method is layout", pipeline.method === "layout", pipeline.method);
    check("no pipeline warnings", !pipeline.warnings?.length, JSON.stringify(pipeline.warnings || []));

    console.log("\n[2/6] Review editor");
    // The studio opens the editor automatically after extraction, so toggle only
    // when it is still collapsed.
    let editorOpen = (await textOf(page)).includes("Hide editor");
    if (!editorOpen) {
      editorOpen = await clickByText(page, "button", "Edit before publishing");
    }
    check("editor opens", editorOpen);
    if (editorOpen) {
      const values = await page.evaluate(() =>
        Array.from(document.querySelectorAll('input[placeholder^="e.g."]')).map(
          (el) => el.value
        )
      );
      check("editor is populated", values.every((value) => value.trim().length > 0), JSON.stringify(values));
      await page.screenshot({ path: path.join(outDir, "02-editor.png"), fullPage: true });
    }

    console.log("\n[3/6] Publish");
    published = await publish("03");
    check("published", Boolean(published.assignedId), published.assignedId || "no id");
    check("first publish is not a duplicate", !published.duplicate);
    check("publish id present", Boolean(published.assignedId));

    console.log("\n[4/6] Detail page");
    if (published.href) {
      await page.goto(`${baseUrl}${published.href}`, { waitUntil: "networkidle2" });
      await page.waitForFunction(() => document.body.innerText.length > 200, { timeout: 30_000 });
      const detail = await textOf(page);
      check("detail shows company", detail.includes(exp.company?.name || ""), exp.company?.name);
      check(
        "detail shows first round",
        exp.rounds?.[0]?.name ? detail.includes(exp.rounds[0].name) : true,
        exp.rounds?.[0]?.name
      );
      const tip = exp.tips?.[0];
      check("detail shows tips", tip ? detail.includes(tip.slice(0, 40)) : true, tip ? tip.slice(0, 60) : "no tips in payload");
      await page.screenshot({ path: path.join(outDir, "04-detail.png"), fullPage: true });
    }

    console.log("\n[5/6] Re-upload for duplicate detection");
    const second = await uploadAndExtract("05");
    const secondExperience = second.experiences?.[0] || {};
    check(
      "second extraction matches company",
      secondExperience.company?.name === exp.company?.name,
      secondExperience.company?.name
    );
    const duplicate = await publish("05");
    check("duplicate detected", duplicate.duplicate, duplicate.assignedId);
    check("duplicate keeps the same id", duplicate.assignedId === published.assignedId, duplicate.assignedId);

    console.log("\n[6/6] Diagnostics");
    check("no page errors", pageErrors.length === 0, pageErrors.join(" | "));
    check("no 5xx responses", httpErrors.length === 0, httpErrors.join(" | "));

    const report = {
      pdf,
      baseUrl,
      generatedAt: new Date().toISOString(),
      checks,
      consoleErrors,
      pageErrors,
      httpErrors,
      experience: {
        company: exp.company,
        candidate: exp.candidate,
        role: exp.job?.role,
        ctc: exp.compensation?.ctc,
        outcome: exp.outcome,
        rounds: exp.rounds?.map((r) => ({
          sequence: r.sequence,
          name: r.name,
          type: r.type,
          questions: r.questions?.length || 0,
          coding: r.coding?.problems?.length || 0,
        })),
        tips: exp.tips?.length || 0,
      },
      pipeline: {
        method: pipeline.method,
        providers: pipeline.providers,
        duration_ms: pipeline.duration_ms,
        warnings: pipeline.warnings,
      },
      published,
      screenshots: outDir,
    };

    fs.writeFileSync(path.join(outDir, "report.json"), JSON.stringify(report, null, 2));
    console.log(`\nReport: ${path.join(outDir, "report.json")}`);
    console.log(`Screenshots: ${outDir}`);

    if (consoleErrors.length) {
      console.log(`Console errors (non-fatal): ${consoleErrors.length}`);
      for (const message of consoleErrors.slice(0, 10)) console.log(`  - ${message}`);
    }

    const failed = checks.filter((item) => !item.ok);
    if (failed.length) {
      console.error(`\n${failed.length} check(s) failed.`);
      process.exitCode = 1;
    } else {
      console.log(`\nAll ${checks.length} browser checks passed.`);
    }
  } catch (error) {
    console.error(`\nE2E failed: ${error.message}`);
    try {
      await page.screenshot({ path: path.join(outDir, "error.png"), fullPage: true });
    } catch {}
    process.exitCode = 1;
  } finally {
    await browser.close();
  }
}

main();
